import {RefSelector, type RefSelectorProps} from '@github-ui/ref-selector'
import {useRef, useState} from 'react'

export interface RefSelectorPartialProps
  extends Pick<
    RefSelectorProps,
    | 'ariaDescribedBy'
    | 'ariaLabelledBy'
    | 'ariaLabel'
    | 'buttonClassName'
    | 'buttonText'
    | 'persistButtonText'
    | 'buttonPrefix'
    | 'showIcon'
    | 'hideShowAll'
    | 'actionListHeadingText'
    | 'cacheKey'
    | 'canCreate'
    | 'closeOnSelect'
    | 'defaultBranch'
    | 'types'
    | 'size'
    | 'allowResizing'
    | 'idEnding'
  > {
  className?: string
  dispatchEvent?: boolean
  formData?: {
    id: string
    name: string
    autosubmit: boolean
  }
  initialRef: string | null
  ownerLogin: string | null
  repoName: string | null
  urlTemplate?: string | null
  urlPlaceholder?: string
}

export function RefSelectorPartial({
  ariaDescribedBy,
  ariaLabelledBy,
  ariaLabel,
  buttonClassName,
  buttonText,
  persistButtonText,
  buttonPrefix,
  showIcon,
  hideShowAll,
  actionListHeadingText,
  cacheKey,
  canCreate,
  className,
  closeOnSelect = true,
  defaultBranch,
  dispatchEvent,
  formData,
  initialRef,
  ownerLogin,
  repoName,
  types,
  size,
  allowResizing,
  idEnding,
  urlTemplate,
  urlPlaceholder = '{{ urlEncodedRefName }}',
}: RefSelectorPartialProps) {
  const [selectedRef, setSelectedRef] = useState(initialRef ?? defaultBranch ?? '')
  const shouldShowDisabledDefaultBranchPicker = ownerLogin === null || cacheKey === null || defaultBranch === null
  const partialRef = useRef<HTMLDivElement>(null)

  const onSelectItem = (item: string) => {
    setSelectedRef(item)

    if (dispatchEvent) {
      // Request an animation frame to ensure event is dispatched after the value of the hidden input is updated
      window.requestAnimationFrame(() => {
        if (partialRef.current) {
          partialRef.current.dispatchEvent(
            new CustomEvent('ref-selector-partial:change', {
              bubbles: true,
              detail: {refName: item, autosubmit: formData?.autosubmit},
            }),
          )
        }
      })
    }
  }

  // Convert URL template to getHref function for navigation.
  // URL templates contain placeholders that get replaced with the selected ref name.
  // This enables server-side URL generation while allowing client-side dynamic replacement.
  // Example: "/owner/repo/compare/{{ urlEncodedRefName }}...main" -> "/owner/repo/compare/v1.0.0...main" (with v1.0.0 URL-encoded)
  const getHref = urlTemplate
    ? (ref: string) => {
        return urlTemplate.replace(urlPlaceholder, encodeURIComponent(ref))
      }
    : undefined

  return (
    <div className={className} data-testid="ref-selector-partial-container" ref={partialRef}>
      {formData && (
        <input
          type="hidden"
          name={formData.name}
          id={formData.id}
          value={selectedRef}
          data-testid="ref-selector-partial-hidden-input"
        />
      )}
      {shouldShowDisabledDefaultBranchPicker && (
        <div className="d-flex">
          <div className="pt-2 d-none" id="explanation-disabled-button">
            Pick a repository first.
          </div>
          <button className="btn d-flex text-eft text-normal mt-1 ml-2" disabled>
            <span>Default Branch</span>
            <span className="dropdown-caret float-right mt-2" />{' '}
          </button>
        </div>
      )}
      {!shouldShowDisabledDefaultBranchPicker && (
        //passing in empty string for the optional params to make linters happy
        //but the scenario won't happpen in practice
        <RefSelector
          ariaDescribedBy={ariaDescribedBy}
          ariaLabelledBy={ariaLabelledBy}
          ariaLabel={ariaLabel}
          cacheKey={cacheKey ?? ''}
          canCreate={canCreate}
          buttonClassName={buttonClassName}
          buttonText={buttonText}
          persistButtonText={persistButtonText}
          buttonPrefix={buttonPrefix}
          showIcon={showIcon}
          hideShowAll={hideShowAll}
          actionListHeadingText={actionListHeadingText}
          closeOnSelect={closeOnSelect}
          currentCommitish={selectedRef}
          defaultBranch={defaultBranch ?? ''}
          onSelectItem={onSelectItem}
          owner={ownerLogin ?? ''}
          repo={repoName ?? ''}
          types={types}
          size={size}
          allowResizing={allowResizing}
          idEnding={idEnding}
          useFocusZone
          getHref={getHref}
        />
      )}
    </div>
  )
}

try{ RefSelectorPartial.displayName ||= 'RefSelectorPartial' } catch {}